/// A slice descriptor with optional start, stop, and step fields.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct Slice {
    pub start: Option<usize>,
    pub stop:  Option<usize>,
    pub step:  Option<usize>,
}

/// Constructs a `Slice` descriptor from the given optional start, stop, and step.
/// 
/// # Panics
/// 
/// - If `step` is `Some(0)`, since the step size must be strictly positive.
/// - If both `start` and `stop` are `Some` and `start > stop`, since the start index
///   must not exceed the stop index.
pub fn s_(start: Option<usize>, stop: Option<usize>, step: Option<usize>) -> Slice {
    if let Some(s) = step {
        assert!(s > 0, "step must be strictly positive");
    }
    if let (Some(a), Some(b)) = (start, stop) {
        assert!(a <= b, "start must be less than or equal to stop");
    }
    Slice { start, stop, step }
}

